//! 🧪️ Independent original currencies reach the actual derived semantic task before paid cancellation.
use super::*;
use semio_framework_value::ErasedSnapshotRetirement;
use semio_framework_os_store_replay_operation::{ArtifactReplayPreparation, ArtifactReplayPreparationStep};
struct CurrencyPreparation{bytes:ManuallyDrop<Option<Vec<u8>>>,closing:bool,copy:usize,capacity:usize,ledger:u64}
impl ArtifactReplayPreparation<u64,u64> for CurrencyPreparation{
 fn advance_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:self.copy,capacity_bytes:self.capacity,depth:1,..Default::default()})}
 fn advance(&mut self,body:usize,g:ArtifactStoreOneItemGrant,c:&mut semio_framework_value_native_owned::native_decoding::NativeDecodeControl<'_>)->Result<ArtifactReplayPreparationStep,ValueError>{assert_eq!(c.ledger_identity(),self.ledger);let d=self.advance_demands(4096).unwrap();assert!(funded(g.retained_grant(),d));assert!(self.bytes.is_none());c.admit_turn_capacity(g.maximum_capacity_bytes)?;c.charge(self.capacity)?;let mut bytes=Vec::new();bytes.try_reserve_exact(self.capacity).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original currency fixture allocation"))?;*self.bytes=Some(bytes);Ok(ArtifactReplayPreparationStep::Pending(RetainedCloneProgress{copied_items:1,copied_bytes:self.copy,retained_capacity_bytes:self.capacity,..Default::default()}))}
 fn take_prepared(&mut self)->Option<ArtifactReplayPrepared<u64,u64>>{None}
 fn cancel(&mut self){self.closing=true;}
 fn begin_close(&mut self){self.closing=true;}
 fn close_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:size_of::<Option<Vec<u8>>>(),release_bytes:self.bytes.as_ref().map_or(0,Vec::capacity),depth:1,..Default::default()})}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(4096)?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
 fn close_step(&mut self,g:RetainedCloneGrant,c:&mut dyn semio_framework_value::OriginalRetirementControl)->Result<RetainedCloneStep,ValueError>{assert!(self.closing);assert_eq!(c.ledger_identity(),self.ledger);let d=self.close_demands(4096)?;if !funded(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}drop(self.bytes.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))}
 fn terminal_is_empty(&self)->bool{self.closing&&self.bytes.is_none()}
}
#[test]
fn original_derived_semantic_task_admits_copy_and_capacity_as_independent_currencies(){
 let law:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();let f=&law["independentAxes"];let mut callback=|_:semio_framework_value_native_owned::native_decoding::NativeDecodeProgress|true;let mut receiving=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(f["ownershipCeiling"].as_u64().unwrap()as usize,&mut callback);let mut recipient=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();receiving.install_retirement_recipient(&mut recipient).unwrap();let ledger=receiving.ledger_identity();let context=ArtifactReplayPreparationContext{mode:ArtifactReplayPreparationMode::Prefix,operation_index:0,generation:7,base_revision:[9;32]};let cursor=CurrencyPreparation{bytes:ManuallyDrop::new(None),closing:false,copy:f["copyBytes"].as_u64().unwrap()as usize,capacity:f["capacityBytes"].as_u64().unwrap()as usize,ledger};
 let mut owner=ArtifactDerivedOperation::<u64,u64>{base:ManuallyDrop::new(None),producer:ManuallyDrop::new(None),registry:None,context,failed_read:ManuallyDrop::new(None),failed_input:ManuallyDrop::new(None),registry_close:ManuallyDrop::new(None),mode:ArtifactDerivedOperationMode::Provisional,policy:protocol::MergePolicy::default(),task:ManuallyDrop::new(Some(ArtifactReplayPreparationTask::new(context,Box::new(cursor)))),task_close:ManuallyDrop::new(None),prepared:ManuallyDrop::new(None),mutation:ManuallyDrop::new(None),retirement:ManuallyDrop::new(None),snapshots:ManuallyDrop::new(None),mutations:ManuallyDrop::new(None),factory_close:std::array::from_fn(|_|None),message:0,accepted:true,ready:false,finished:false,closing:false,progress:Default::default()};
 let d=owner.demands(7,[9;32],4096).unwrap();assert!(d.copy_bytes+d.capacity_bytes>4096);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:f["copyGrant"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityGrant"].as_u64().unwrap()as usize,maximum_release_bytes:65536,maximum_depth:64};
 for denied in [RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}]{let(s,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(7,[9;32],4096,denied,&mut receiving,&mut||false).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}
 let(s,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(7,[9;32],4096,g,&mut receiving,&mut||false).unwrap());assert_eq!(s.progress().copied_bytes,d.copy_bytes);assert_eq!(s.progress().retained_capacity_bytes,d.capacity_bytes);assert_eq!((h.requested_bytes,h.released_bytes),(d.capacity_bytes,0));assert_eq!(receiving.ledger_identity(),ledger);owner.cancel();assert!(owner.requires_original_control());assert_eq!(owner.close_step(RetainedCloneGrant{maximum_items:0,..g}).unwrap().progress(),Default::default());let missing=owner.close_step(g).unwrap_err();assert_eq!(missing.kind,ValueRefusalKind::UnsupportedOwner);let mut foreign_recipient=semio_framework_value_native_owned::native_decoding::NativeDecodeRetirementRecipient::new();let mut foreign_callback=|_:semio_framework_value_native_owned::native_decoding::NativeDecodeProgress|false;let mut foreign=semio_framework_value_native_owned::native_decoding::NativeDecodeControl::new(65536,&mut foreign_callback);foreign.install_retirement_recipient(&mut foreign_recipient).unwrap();let before=owner.progress();let foreign=foreign.with_retirement(g,|control|owner.close_step_controlled(g,control)).unwrap_err();assert_eq!(foreign.kind,ValueRefusalKind::OwnershipLimit);assert_eq!(serde_json::json!({"unfunded":"Progress","missingControl":format!("{:?}",missing.kind),"foreignControl":format!("{:?}",foreign.kind),"preservesProgress":owner.progress()==before}),law["retirementCustody"]);assert_eq!(owner.progress(),before);assert!(owner.task.is_some());while !owner.terminal_is_empty(){let d=owner.demands(7,[9;32],4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(s,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||receiving.with_retirement(g,|control|owner.close_step_controlled(g,control)).unwrap());assert_eq!((h.requested_bytes,h.released_bytes),(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert_eq!((semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner)).1.requested_bytes),0);
}
